import test from 'node:test';
import assert from 'node:assert/strict';
import { dedupeById } from '../src/dedupe.mjs';
test('keeps the first duplicate in original order', () => {
  const a = { id: 'a', value: 1 };
  const b = { id: 'b', value: 2 };
  assert.deepEqual(dedupeById([a, b, { id: 'a', value: 3 }]), [a, b]);
});

