import test from 'node:test';
import assert from 'node:assert/strict';
import { retry } from '../src/retry.mjs';
test('returns after a transient failure', async () => {
  let calls = 0;
  const value = await retry(async () => { if (++calls < 2) throw new Error('temporary'); return 'ok'; }, { maxAttempts: 3, delayMs: 0, shouldRetry: () => true, sleep: async () => {} });
  assert.equal(value, 'ok');
  assert.equal(calls, 2);
});
